## Code Example
```javascript
interface FlagStrategy {
  evaluate(user, flag): boolean;
}
class BooleanFlagStrategy implements FlagStrategy {
  evaluate(user, flag) { return flag.value; }
}
class PercentFlagStrategy implements FlagStrategy {
  evaluate(user, flag) { return (user.id % 100) < flag.percent; }
}
class UserSegmentFlagStrategy implements FlagStrategy {
  evaluate(user, flag) { return flag.segments.includes(user.segment); }
}

class FlagEvaluator {
  constructor(strategy) { this.strategy = strategy; }
  evaluate(user, flag) { return this.strategy.evaluate(user, flag); }
  setStrategy(s) { this.strategy = s; }
}
```

